  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "The closest structural analogue, bicuculline, was directly measured to penetrate rat brain in a dose-dependent manner by LC-MS/MS, demonstrating that the phthalideisoquinoline scaffold can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nuciferine, a related aporphine alkaloid, reached brain concentrations nearly equal to plasma in rats, showing effective BBB penetration for this alkaloid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Hernandezine achieved a brain Cmax close to plasma Cmax after intravenous dosing in rats, supporting CNS access for polycyclic alkaloids with similar physicochemical features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Schisandrin B had a logPSFu,brain of -3.2 and detectable brain concentrations in mice, indicating meaningful BBB permeation despite moderate structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Boldine reached high brain concentrations (18–24 µM) after oral dosing in rats, demonstrating that related alkaloids with multiple methoxy/phenolic groups can achieve substantial CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is noscapine, a phthalideisoquinoline alkaloid with high passive BBB plausibility. Direct evidence from the closest analogue bicuculline and multiple related alkaloids (nuciferine, hernandezine, schisandrin B, boldine) shows effective brain/CSF penetration. No contradictory evidence was identified, so the prediction is pass for meaningful CNS access.",
  "evidence_gaps": [
    "No direct noscapine-specific brain concentration data were provided in the evidence set.",
    "Efflux transporter liability was not directly measured for the query or most analogues.",
    "The specific brain tumor/glioma condition was not directly tested in the cited studies."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

